'use strict';

// MODULES //

var Routine = require( './routine.js' );


// MAIN //

/**
* WebAssembly routine to compute the arithmetic mean of a single-precision floating-point strided array, ignoring `NaN` values, using Welford's algorithm with extended accumulation.
* @name dsnanmeanwd
* @type {Routine}
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* // Define a strided array:
* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
*
* // Perform operation:
* var v = dsnanmeanwd.main( 4, x, 1 );
* // returns ~0.3333
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* // Define a strided array:
* var x = new Float32Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0, NaN, NaN ] );
*
* // Perform operation:
* var v = dsnanmeanwd.ndarray( 5, x, 2, 1 );
* // returns 1.25
*/
var dsnanmeanwd = new Routine();
dsnanmeanwd.initializeSync(); // eslint-disable-line node/no-sync


// EXPORTS //

module.exports = dsnanmeanwd;
